'use strict';
const app=document.querySelector('#app'),account=document.querySelector('#account');
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), letter=i=>'ABCD'[i]||'—', pct=(n,total=40)=>n==null||!total?'—':(n/total*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%', date=d=>d?new Date(d).toLocaleString('pt-BR'):'—';
const fmtTime=ms=>ms==null?'—':Math.floor(ms/60000)+'m '+String(Math.floor(ms/1000)%60).padStart(2,'0')+'s';

const heroScene=`<div class="hero-art" aria-hidden="true"><div class="arena-halo"></div><div class="arena-platform"></div><div class="arena-particles"><i></i><i></i><i></i><i></i><i></i><i></i></div><canvas class="hero-avatar" data-avatar="hero" data-color="#56e9aa"></canvas><span class="art-tag">ARENA / 01</span><span class="art-tag alt">NÍVEL COMPETITIVO</span></div>`;
const bannerScene=`<div class="banner-art" aria-hidden="true"><div class="arena-halo"></div><div class="arena-platform"></div><canvas class="hero-avatar" data-avatar="hero" data-color="#56e9aa"></canvas></div>`;
let user,quiz,index=0,busy=false,timer,courseId=1,reportId=1;
const qs=()=>"?course="+courseId;
async function branding(){const b=await api("/api/branding");const el=$(".brand .logo");el.innerHTML=b.hasLogo?`<img src="/logo?v=${encodeURIComponent(b.version||'22')}" alt="Logo institucional">`:`<img src="/default-logo.png" alt="Logo Bioquality">`;el.classList.toggle("custom-logo",b.hasLogo);}
async function api(url,data){const r=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let v;try{v=await r.json();}catch{throw Error('Servidor indisponível ou resposta inválida (HTTP '+r.status+'). Confira a implantação.');}if(!r.ok){const e=Error(v.error||'Falha na solicitação.');e.status=r.status;throw e;}return v;}
function toast(msg){const el=$('#toast');el.textContent=msg;el.hidden=false;clearTimeout(timer);timer=setTimeout(()=>el.hidden=true,4500);}
function error(e){toast(e.message||'Erro de conexão.');}function set(h){stopAttendance();stopLoginCarousel();stopCampaignPlayback();app.innerHTML=h;window.scrollTo(0,0);startCampaignPlayback(app);}
function header(){account.innerHTML=user?`<span>${esc(user.name)} · ${user.role==='admin'?'Administração':user.role==='instructor'?'Instrutor':'Aluno'}</span><button class="secondary" id="logout">Sair</button>`:'';if(user)$('#logout').onclick=async()=>{try{if(busy)return;await api('/api/logout',{});user=null;quiz=null;index=0;login();}catch(e){error(e)}};}
function login(){header();set(`<div class="login-grid"><section class="hero"><span class="eyebrow">Plataforma de conhecimento</span><h1>Desafie seus limites.<br><em>Conquiste a arena.</em></h1><p>Transforme seu conhecimento em desempenho. Avance a cada acerto e dispute o topo da classificação.</p>${heroScene}<div class="hero-stats"><div><b>01</b><small>Estude</small></div><div><b>02</b><small>Compita</small></div><div><b>03</b><small>Evolua</small></div></div></section><section class="panel"><span class="eyebrow">Portal de aprendizagem</span><h2>Acesse sua conta</h2><p class="muted">Utilize o usuário e a senha da sua conta. O mesmo portal atende alunos e administradores.</p><form id="login-form"><label for="login">Usuário</label><input id="login" name="login" required autocomplete="username" maxlength="80" placeholder="Seu usuário"><label for="password">Senha</label><input id="password" name="password" type="password" required autocomplete="current-password" maxlength="200" placeholder="Sua senha"><div class="marketing-login"><label for="whatsapp">WhatsApp <span class="muted small">(opcional)</span></label><input id="whatsapp" name="whatsapp" type="tel" inputmode="tel" autocomplete="tel" maxlength="40" placeholder="DDD + número"><label class="checkline marketing-consent"><input type="checkbox" id="marketing-consent"> <span>Autorizo a Bioquality a enviar ofertas, cursos e novidades ao meu WhatsApp. Confirmo que o número informado é meu. Posso cancelar a autorização a qualquer momento, sem perder acesso.</span></label><p class="small muted">Sem código de confirmação. Seu contato só será salvo após o login se você autorizar as divulgações.</p></div><button class="full" type="submit">Entrar na plataforma</button><p class="error" id="login-error"></p></form><button type="button" class="secondary full" id="register">Criar minha conta</button><p class="small muted">Não possui acesso? Crie sua conta ou solicite acesso ao responsável pelo treinamento.</p></section></div>`);mountLoginCarousel();$('#register').onclick=()=>registerPage().catch(error);$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await api('/api/login',{...Object.fromEntries(new FormData(f)),marketingConsent:$('#marketing-consent').checked});await enter();}catch(e){if($('#login-error'))$('#login-error').textContent=e.message;else error(e);b.disabled=false;}};}
async function registerPage(){
 const cfg=await api('/api/registration/config');
 if(!cfg.enabled){set(`<section class="panel registration-panel"><button type="button" class="secondary" id="register-back">← Voltar ao login</button><h1>Criar minha conta</h1><p>O cadastro público está desativado. Procure a administração para solicitar acesso.</p></section>`);$('#register-back').onclick=login;return;}
 set(`<section class="panel registration-panel"><button type="button" class="secondary" id="register-back">← Voltar ao login</button><span class="eyebrow">CADASTRO DE ALUNO</span><h1>Criar minha conta</h1><p class="muted">Preencha seus dados para criar sua conta.</p><form id="registration-form"><label>Nome completo<input name="name" required maxlength="120" autocomplete="name"></label><fieldset class="registration-education"><legend>Empresa / vínculo profissional</legend><label class="checkline"><input type="radio" name="companyStatus" value="company" required> Trabalho em uma empresa</label><label class="checkline"><input type="radio" name="companyStatus" value="none" required> Não possuo vínculo com nenhuma empresa</label><label class="checkline"><input type="radio" name="companyStatus" value="unknown" required> Não sei informar a empresa</label><div id="registration-company-wrap" hidden><label>Selecionar empresa cadastrada<select name="companyId" disabled><option value="">Selecione uma empresa</option></select></label><p class="muted small" id="registration-company-message" role="status"></p></div></fieldset><label>Usuário<input name="login" required minlength="3" maxlength="80" pattern="[a-zA-Z0-9._@\\-]{3,80}" autocomplete="username" placeholder="Sem espaços"></label><label>Senha<input name="password" required type="password" minlength="8" maxlength="100" autocomplete="new-password"></label><label>Confirmar senha<input name="passwordConfirm" required type="password" minlength="8" maxlength="100" autocomplete="new-password"></label><label>Celular com DDD (obrigatório)<input name="phone" required type="tel" inputmode="tel" maxlength="32" autocomplete="tel" placeholder="(94) 99999-9999"></label><fieldset class="registration-education"><legend>Escolaridade e interesse profissional</legend><label>Situação escolar<select name="educationStatus" required><option value="">Selecione</option><option>Cursando atualmente</option><option>Última série concluída</option><option>Nenhuma série concluída</option><option>Prefiro não informar</option></select></label><div id="education-grade-wrap" hidden><label><span id="education-grade-label">Ano / série / etapa escolar</span><input name="educationGrade" maxlength="120" list="education-grade-options" placeholder="Selecione ou digite sua série"></label><datalist id="education-grade-options">${[...Array.from({length:9},(_,i)=>`${i+1}º ano do Ensino Fundamental`),...Array.from({length:3},(_,i)=>`${i+1}º ano do Ensino Médio`),'Ensino Médio concluído','EJA – Ensino Fundamental','EJA – Ensino Médio','Ensino Técnico','Ensino Superior'].map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist><p class="muted small">Se não encontrar sua série, digite a etapa correspondente.</p></div><label>Curso técnico por competência de interesse<input name="technicalInterest" required maxlength="150" list="technical-interest-options" placeholder="Ex.: Técnico em Segurança do Trabalho"></label><datalist id="technical-interest-options"><option value="Ainda não decidi"></option><option value="Não tenho interesse"></option><option value="Prefiro não informar"></option></datalist><p class="muted small">Digite o nome do curso desejado ou indique que ainda não decidiu. O interesse informado não equivale à matrícula nem confirma a oferta ou elegibilidade.</p></fieldset><label class="checkline"><input name="acceptPhone" type="checkbox" required> <span>Estou ciente de que meu celular será armazenado para identificação da conta e que as informações escolares e de interesse serão utilizadas para acompanhamento educacional. Não haverá confirmação de titularidade do telefone. Isso não autoriza publicidade.</span></label><button type="submit" class="full">Criar conta e acessar</button><p class="error" id="registration-error" role="alert"></p></form></section>`);$('#register-back').onclick=login;const regForm=$('#registration-form'),school=regForm.elements.educationStatus,grade=regForm.elements.educationGrade;function syncEducation(){const needs=['Cursando atualmente','Última série concluída'].includes(school.value);$('#education-grade-wrap').hidden=!needs;grade.required=needs;grade.disabled=!needs;if(!needs)grade.value='';$('#education-grade-label').textContent=school.value==='Cursando atualmente'?'Ano / série que está cursando':'Última série ou etapa concluída';}school.onchange=syncEducation;syncEducation();
 const companyWrap=$('#registration-company-wrap'),companySelect=regForm.elements.companyId,companyMessage=$('#registration-company-message');
 const companies=(cfg.companies||[]).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR',{sensitivity:'base'}));
 companySelect.innerHTML='<option value="">Selecione uma empresa</option>'+companies.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
 companyMessage.textContent=companies.length?'':'Nenhuma empresa ativa cadastrada. Solicite o cadastro à administração.';
 function syncCompany(){const needs=regForm.elements.companyStatus.value==='company';companyWrap.hidden=!needs;companySelect.disabled=!needs;companySelect.required=needs;if(!needs)companySelect.value='';}
 regForm.querySelectorAll('[name="companyStatus"]').forEach(el=>el.onchange=syncCompany);syncCompany();regForm.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,btn=f.querySelector('button[type=submit]'),data=Object.fromEntries(new FormData(f));if(data.password!==data.passwordConfirm){$('#registration-error').textContent='As senhas não coincidem.';return;}delete data.passwordConfirm;data.acceptPhone=f.elements.acceptPhone.checked;btn.disabled=true;$('#registration-error').textContent='';try{await api('/api/registration/create',data);if(f.isConnected)await enter();}catch(err){if(f.isConnected)$('#registration-error').textContent=err.message;}finally{btn.disabled=false;}};
}

async function enter(){user=await api('/api/me');header();if(user.role==='admin')await admin();else if(user.role==='instructor')await instructor();else {const requested=Number(new URL(location.href).searchParams.get('course'));if(Number.isSafeInteger(requested)&&requested>0){try{await openCourse(requested);return;}catch(e){if(e.status!==404)throw e;}}await student();}}
const metric=(title,n,desc)=>`<div class="metric"><span>${title}</span><strong>${esc(n)}</strong>${desc}</div>`;
async function student(){const url=new URL(location.href);url.searchParams.delete('course');history.replaceState(null,'',url);const courses=await api('/api/courses');const campaigns=await api('/api/campaigns').catch(()=>[]);set(`<span class="eyebrow">Área do aluno</span><h1>Minhas matérias</h1><p class="muted">Olá, ${esc(user.name)}. Escolha uma avaliação disponível.</p><section class="panel attendance-student" id="student-attendance"><h2>Lista de presença</h2><p>Carregando listas...</p></section><button class="secondary" id="marketing-prefs">Meu WhatsApp e preferências</button><section class="arena-banner"><div><span class="eyebrow">COMPETIÇÃO AO VIVO</span><h2>Sua próxima conquista começa aqui.</h2><p>Avance a cada acerto e dispute a liderança em tempo real.</p><a class="btn arena-cta" href="/corrida">Entrar na arena</a></div>${bannerScene}</section>${campaignDisplay(campaigns)}<div class="course-grid">${courses.map(c=>`<section class="panel course-card"><span class="pill ${c.attempt?.submitted?'done':''}">${c.attempt?.submitted?'Concluído':c.attempt?'Em andamento':'Disponível'}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.description)}</p><p>${c.total} questões ${c.attempt?.submitted?' · '+esc(pct(c.attempt.score,c.total)):''}</p><button data-course="${c.id}">${c.attempt?.submitted?'Ver resultado':c.attempt?'Continuar':'Acessar matéria'}</button></section>`).join('')||'<p>Nenhuma matéria publicada.</p>'}</div>`);mountStudentAttendance();$('#marketing-prefs').onclick=()=>marketingPreferences().catch(error);app.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>openCourse(Number(b.dataset.course)).catch(error));}
async function openCourse(id){courseId=id;quiz=await api('/api/quiz'+qs());const url=new URL(location.href);url.searchParams.set('course',String(id));history.replaceState(null,'',url);if(quiz.attempt?.submitted)return result(await api('/api/result'+qs()));if(quiz.attempt){index=quiz.questions.findIndex(q=>!(q.id in quiz.attempt.answers));if(index<0)index=quiz.questions.length-1;return renderQuiz();}const n=quiz.questions.length;const preQuizAds=await api('/api/campaigns?placement=quiz&course='+id).catch(()=>[]);set(`<button class="secondary" id="back">← Minhas matérias</button><p></p><span class="eyebrow">Área do aluno</span><h1>${esc(quiz.title)}</h1><p class="muted">Revise os fundamentos antes de iniciar.</p>${campaignDisplay(preQuizAds,'quiz')}${CourseMedia.render(quiz.preMedia,"Apresentação do treinamento")}<div class="metrics">${metric('QUESTÕES',n,'Múltipla escolha')}${metric('PONTUAÇÃO',n,'Pontos máximos')}${metric('AVALIAÇÃO',1,'Tentativa por matéria')}${metric('PROGRESSO','0%','Não iniciado')}</div><section class="panel"><h2>Fundamentação teórica</h2><div class="study">${quiz.theory.map(t=>`<article><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p></article>`).join('')||'<p class="muted">Sem conteúdo complementar.</p>'}</div><p class="muted small">Assinale uma alternativa por questão. O progresso é salvo automaticamente. A entrega é definitiva.</p><button id="start">Iniciar avaliação</button></section>`);$('#back').onclick=()=>student().catch(error);$('#start').onclick=async e=>{e.currentTarget.disabled=true;try{await api('/api/start',{courseId});await openCourse(courseId);}catch(e){error(e);if($('#start'))$('#start').disabled=false;}};}
function renderQuiz(){const q=quiz.questions[index],a=quiz.attempt.answers,n=Object.keys(a).length,total=quiz.questions.length;set(`<button class="secondary" id="courses">← Minhas matérias</button><p></p><span class="eyebrow">Avaliação técnica</span><h1>${esc(quiz.title)}</h1><p class="muted">${n} de ${total} respondidas · ${Math.round(n/total*100)}% concluído</p><div class="progress"><progress max="${total}" value="${n}" aria-label="Progresso"></progress></div>${CourseMedia.render(quiz.quizMedia,"Material de apoio da avaliação")}<div class="quiz-grid"><section class="panel"><span class="eyebrow">Questão ${index+1} / ${total} · ${esc(q.topic)}</span><h2 class="question-title">${esc(q.question)}</h2>${CourseMedia.render(q.media)}<div role="group" aria-label="Alternativas">${q.options.map((o,i)=>`<button class="option ${a[q.id]===i?'selected':''}" aria-pressed="${a[q.id]===i}" data-option="${i}"><span class="letter">${letter(i)}</span><span>${esc(o)}</span></button>`).join('')}</div><div class="quiz-nav"><button class="secondary" id="prev" ${index===0?'disabled':''}>← Anterior</button><button id="next" ${index===total-1?'disabled':''}>Próxima →</button></div><p class="muted small">As alternativas são salvas ao selecionar. O gabarito será exibido após a entrega.</p></section><aside class="panel sticky"><h3>Navegação</h3><p class="muted small">Selecione uma questão para revisar.</p><div class="number-grid">${quiz.questions.map((v,i)=>`<button data-index="${i}" class="${v.id in a?'done':''} ${i===index?'current':''}" aria-label="Questão ${v.id}">${v.id}</button>`).join('')}</div><button class="full" id="finish" ${n!==total?'disabled':''}>Entregar avaliação</button><p class="muted small">${total-n?`${total-n} questões pendentes.`:'Todas as questões respondidas.'} A entrega é definitiva.</p></aside></div>`);app.querySelectorAll('[data-option]').forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;try{const v=Number(b.dataset.option);await api('/api/answer',{courseId,id:q.id,option:v});a[q.id]=v;renderQuiz();}catch(e){error(e)}finally{busy=false;}});function go(i){if(!busy&&i>=0&&i<total){index=i;renderQuiz();}}$('#courses').onclick=()=>{if(!busy)student().catch(error);};$('#prev').onclick=()=>go(index-1);$('#next').onclick=()=>go(index+1);app.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>go(Number(b.dataset.index)));$('#finish').onclick=async()=>{if(busy||!confirm('Entregar a avaliação? Você não poderá alterar as respostas.'))return;busy=true;try{await api('/api/submit',{courseId});result(await api('/api/result'+qs()));}catch(e){error(e)}finally{busy=false;}};}
function result(r,adminView=false){const a=r.attempt,groups=Object.create(null),total=r.questions.length;for(const q of r.questions){groups[q.topic]??={n:0,ok:0};groups[q.topic].n++;groups[q.topic].ok+=q.selected===q.correct?1:0;}set(`<div class="actions no-print"><button class="secondary" id="back">← Voltar</button><button class="secondary" id="print">Imprimir / salvar PDF</button></div><p></p><section class="result-head"><div><span>RELATÓRIO INDIVIDUAL · CONCLUÍDO</span><h1>${esc(adminView?r.student.name:user.name)}</h1><p>${esc(r.title)}</p><p>${a.score} acertos · ${total-a.score} erros · ${esc(date(a.submitted))}</p><p>Tempo: ${fmtTime(a.durationMs)} · Classificação: ${a.points?.toFixed(2)??'—'} / 100 pontos</p></div><div class="score"><b>${esc(pct(a.score,total))}</b><span>${a.score} / ${total} pontos</span></div></section><section class="panel"><h2>Desempenho por conteúdo</h2>${Object.entries(groups).map(([k,v])=>`<div class="topic-row"><span>${esc(k)}</span><span><progress max="${v.n}" value="${v.ok}"></progress> ${v.ok}/${v.n}</span></div>`).join('')}</section><section class="panel report-panel"><h2>Gabarito comentado</h2><p class="muted">Abra cada questão para conferir a resposta e a justificativa.</p>${r.questions.map(q=>`<details class="review"><summary><span class="${q.selected===q.correct?'correct':'wrong'}">${q.selected===q.correct?'✓':'✕'}</span> ${q.id}. ${esc(q.question)}</summary>${CourseMedia.render(q.media)}<p>Resposta marcada: <b>${letter(q.selected)} — ${esc(q.options[q.selected]||'Não respondida')}</b></p><p class="correct">Resposta correta: <b>${letter(q.correct)} — ${esc(q.options[q.correct])}</b></p><p class="muted">${esc(q.explanation)}</p></details>`).join('')}</section>`);$('#print').onclick=()=>{document.querySelectorAll('details').forEach(d=>d.open=true);window.print();};$('#back').onclick=()=> (adminView?admin():student()).catch(error);}
async function admin(){const courses=await api('/api/admin/courses');if(!courses.some(c=>c.id===reportId))reportId=courses[0].id;const query='?course='+reportId,rows=await api('/api/report'+query),completed=rows.filter(r=>r.score!==null),mean=completed.length?completed.reduce((s,r)=>s+r.score/r.total,0)/completed.length*100:null;set(`<div class="title-row admin-heading"><div><span class="eyebrow">Administração</span><h1>Gestão de avaliações</h1><p class="muted">Cadastre alunos e acompanhe os resultados de cada matéria.</p></div><div class="actions"><a class="btn" href="/corrida">Arena ao vivo</a><button id="manage">Matérias e questões</button><button id="attendance-admin">Listas de presença</button><button id="users-admin">Usuários e perfis</button><button id="advertising">Publicidade e vídeos</button><button id="marketing-contacts">Contatos WhatsApp</button><button id="login-carousel-admin">Carrossel de login</button><button class="secondary" id="backup-admin">Backup dos dados</button><button class="secondary" id="brand">Alterar logo</button><button class="secondary" id="refresh">Atualizar</button><a class="btn" href="/api/report.csv${query}">Exportar CSV</a><button class="secondary" id="print">Imprimir</button></div></div><section class="arena-banner admin-banner"><div><span class="eyebrow">CENTRAL DE COMPETIÇÕES</span><h2>Comande a competição.</h2><p>Abra rodadas, acompanhe os personagens e projete o ranking ao vivo.</p><a class="btn arena-cta" href="/corrida">Abrir central de corridas</a></div>${bannerScene}</section><div class="metrics">${metric('ALUNOS CADASTRADOS',rows.length,'Total de acessos')}${metric('CONCLUÍDOS',completed.length,'Avaliações entregues')}${metric('EM ANDAMENTO',rows.filter(r=>r.status==='Em andamento').length,'Avaliações iniciadas')}${metric('MÉDIA DE ACERTOS',pct(mean,100),'Entre os concluídos')}</div><section class="panel no-print"><h2>Cadastrar aluno</h2><form id="create"><div class="form-grid"><div><label for="name">Nome completo</label><input id="name" name="name" maxlength="120" required placeholder="Nome do participante"></div><div><label for="company">Empresa / turma</label><input id="company" name="company" maxlength="120" placeholder="Opcional"></div><div><label for="student-login">Usuário</label><input id="student-login" name="login" required minlength="3" maxlength="80" placeholder="ex: aluno01" autocomplete="off"></div><div><label for="student-password">Senha inicial</label><input id="student-password" name="password" type="password" minlength="8" maxlength="100" required autocomplete="new-password" placeholder="Mínimo 8 caracteres"></div></div><button type="submit" class="full">Criar acesso individual</button><p class="small muted">Compartilhe as credenciais somente com o aluno. Uma tentativa por matéria.</p></form></section><section class="panel report-panel"><h2>Relatório de pontuação</h2><label for="report-course">Matéria</label><select id="report-course">${courses.map(c=>`<option value="${c.id}" ${c.id===reportId?'selected':''}>${esc(c.title)}</option>`).join('')}</select><input id="filter" class="filter no-print" placeholder="Buscar aluno, usuário ou turma" aria-label="Buscar aluno"><div class="table-wrap"><table><thead><tr><th>Posição</th><th>Aluno / usuário</th><th>Empresa / turma</th><th>Situação</th><th>Respondidas</th><th>Acertos</th><th>Erros</th><th>Nota %</th><th>Tempo</th><th>Bônus tempo</th><th>Pontos finais</th><th>Conclusão</th><th class="no-print">Ações</th></tr></thead><tbody id="rows"></tbody></table></div></section>`);
function fill(){let term=$('#filter').value.toLowerCase().trim(),filtered=rows.filter(r=>[r.name,r.login,r.company,r.status].join(' ').toLowerCase().includes(term));$('#rows').innerHTML=filtered.length?filtered.map(r=>`<tr><td>${r.rank??'—'}</td><td><b>${esc(r.name)}</b><br><span class="muted small">${esc(r.login)}</span></td><td>${esc(r.company||'—')}</td><td><span class="pill ${r.submitted?'done':r.started?'pending':''}">${esc(r.status)}</span></td><td>${r.answered}/${r.total}</td><td>${r.score??'—'}</td><td>${r.score===null?'—':r.total-r.score}</td><td><b>${esc(pct(r.score,r.total))}</b></td><td>${fmtTime(r.durationMs)}</td><td>${r.timePoints?.toFixed(2)??'—'}</td><td><b>${r.points?.toFixed(2)??'—'}</b></td><td>${esc(date(r.submitted))}</td><td class="no-print"><div class="actions">${r.submitted?`<button class="secondary" data-report="${r.id}">Ver</button>`:''}${r.role==='instructor'?'':`<button class="secondary" data-password="${r.id}">Senha</button>`}</div></td></tr>`).join(''):'<tr><td colspan="13" class="muted">Nenhum aluno encontrado.</td></tr>';app.querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{try{result(await api('/api/report/'+b.dataset.report+query),true)}catch(e){error(e)}});app.querySelectorAll('[data-password]').forEach(b=>b.onclick=async()=>{const password=prompt('Nova senha do aluno (mínimo 8 caracteres):');if(password===null)return;try{await api('/api/password',{id:Number(b.dataset.password),password});toast('Senha atualizada. Sessões anteriores encerradas.');}catch(e){error(e)}});}
fill();$('#attendance-admin').onclick=()=>attendanceAdmin().catch(error);$('#users-admin').onclick=()=>usersAdmin().catch(error);$('#marketing-contacts').onclick=()=>marketingContacts().catch(error);$('#login-carousel-admin').onclick=()=>manageLoginCarousel().catch(error);$('#backup-admin').onclick=()=>backupPage().catch(error);$('#advertising').onclick=()=>advertising().catch(error);$('#manage').onclick=()=>manage().catch(error);$('#brand').onclick=()=>brandPage().catch(error);$('#report-course').onchange=e=>{reportId=Number(e.target.value);admin().catch(error);};$('#filter').oninput=fill;$('#refresh').onclick=()=>admin().catch(error);$('#print').onclick=()=>window.print();$('#create').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await api('/api/students',Object.fromEntries(new FormData(f)));await admin();toast('Acesso do aluno criado com sucesso.');}catch(e){error(e);b.disabled=false;}};}
async function boot(){try{const health=await api('/api/health');if(!health.ready){user=null;header();set(`<section class="panel"><span class="eyebrow">Diagnóstico da implantação</span><h1>Configuração necessária</h1><p>${esc(health.message)}</p><p class="muted">O servidor está acessível. O responsável pela hospedagem deve ajustar a configuração e reimplantar.</p><button id="retry">Verificar novamente</button></section>`);$('#retry').onclick=boot;return;}branding().catch(()=>{});try{await enter();}catch(e){user=null;login();if(e.status!==401)error(e);}}catch(e){user=null;header();set(`<section class="panel"><h1>Não foi possível conectar ao servidor</h1><p>${esc(e.message)}</p><button id="retry">Tentar novamente</button></section>`);$('#retry').onclick=boot;}}
async function brandPage(){const b=await api('/api/branding');set(`<button class="secondary" id="back">← Administração</button><p></p><section class="panel"><span class="eyebrow">Identidade visual</span><h1>Logo da plataforma</h1><p class="muted">A imagem aparece no cabeçalho do login, da área dos alunos e da administração.</p>${b.hasLogo?'<img class="brand-preview" src="/logo" alt="Logo atual">':'<p>Identidade visual padrão da Bioquality.</p>'}<form id="logo-form"><label for="logo-file">Nova logo (PNG, JPEG ou WebP, até 1 MB)</label><input type="file" id="logo-file" accept="image/png,image/jpeg,image/webp" required><button type="submit">Salvar logo</button></form><p></p><button class="secondary" id="remove-logo" ${b.hasLogo?'':'disabled'}>Restaurar logo padrão</button></section>`);$('#back').onclick=()=>admin().catch(error);$('#logo-form').onsubmit=async e=>{e.preventDefault();const f=$('#logo-file').files[0],btn=e.currentTarget.querySelector('button');if(!f||f.size>1000000||!['image/png','image/jpeg','image/webp'].includes(f.type))return toast('Selecione PNG, JPEG ou WebP de até 1 MB.');btn.disabled=true;try{const logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});await api('/api/admin/branding',{logo});await branding();await brandPage();toast('Logo atualizada.');}catch(e){error(e);btn.disabled=false;}};$('#remove-logo').onclick=async()=>{try{await api('/api/admin/branding',{logo:null});await branding();await brandPage();toast('Logo padrão restaurada.');}catch(e){error(e)}};}
async function manage(){const courses=await api('/api/admin/courses');set(`<div class="title-row"><div><button class="secondary" id="back">Voltar ao painel</button><p></p><span class="eyebrow">Banco de conteúdos</span><h1>Matérias e questões</h1><p class="muted">Crie avaliações, textos de estudo e gabaritos. Publique quando estiverem prontos.</p></div><button id="new-course">+ Nova matéria</button></div><div class="course-grid">${courses.map(c=>`<section class="panel course-card"><span class="pill ${c.published?'done':'pending'}">${c.published?'Publicada':'Rascunho / arquivada'}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.description)}</p><p>${c.questions.length} questões · ${c.theory.length} textos</p><button data-edit="${c.id}">Editar matéria</button>${user.role==='admin'?`<button class="secondary" data-course-video="${c.id}">Publicidade vinculada</button>`:''}</section>`).join('')}</div>`);$('#back').onclick=()=>staffHome().catch(error);$('#new-course').onclick=()=>editCourse({title:'',description:'',published:false,theory:[],questions:[]});app.querySelectorAll('[data-course-video]').forEach(b=>b.onclick=()=>campaignEditor({title:'',description:'',cta:'',url:'',youtube:'',published:false,placements:['quiz','arena'],courseId:Number(b.dataset.courseVideo)}).catch(error));app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCourse(structuredClone(courses.find(c=>c.id===Number(b.dataset.edit)))));}
function editCourse(draft){let dirty=false,uploading=false;draft.preMedia??=[];draft.quizMedia??=[];draft.questions.forEach(q=>q.media??=[]);const mediaList=slot=>slot==='pre'?draft.preMedia:slot==='top'?draft.quizMedia:draft.questions[Number(slot)].media;const capture=()=>{for(const el of app.querySelectorAll('[data-media-slot]')){const list=mediaList(el.dataset.mediaSlot);el.querySelectorAll('[data-media-caption]').forEach(input=>{list[Number(input.dataset.mediaCaption)].caption=input.value;});}draft.title=$('#course-title').value;draft.description=$('#course-desc').value;draft.published=$('#published').checked;draft.theory=Array.from(app.querySelectorAll('.theory-edit'),el=>({title:el.querySelector('[name="title"]').value,text:el.querySelector('[name="text"]').value}));draft.questions=Array.from(app.querySelectorAll('.question-edit'),(el,i)=>({id:i+1,topic:el.querySelector('[name="topic"]').value,question:el.querySelector('[name="question"]').value,options:Array.from(el.querySelectorAll('[name="option"]'),x=>x.value),correct:Number(el.querySelector('[name="correct"]').value),explanation:el.querySelector('[name="explanation"]').value,media:draft.questions[i].media}));};
function draw(){set(`<button class="secondary" id="back">← Matérias</button><p></p><span class="eyebrow">Editor de avaliação</span><h1>${draft.id?'Editar matéria':'Nova matéria'}</h1><form id="course-form"><section class="panel"><h2>Informações gerais</h2><label for="course-title">Nome da matéria</label><input id="course-title" required maxlength="150" value="${esc(draft.title)}"><label for="course-desc">Descrição</label><textarea id="course-desc" maxlength="1500" rows="3">${esc(draft.description)}</textarea><label class="checkline"><input type="checkbox" id="published" ${draft.published?'checked':''}> Publicar para todos os alunos</label><p class="muted small">Desmarque para arquivar ou manter como rascunho. Avaliações já iniciadas e concluídas preservam suas questões e pontuações originais.</p></section><section class="panel"><h2>Apresentação antes do quiz</h2><p class="muted">Conteúdo de estudo antes de iniciar a avaliação, inclusive na sala de espera da Arena.</p>${CourseMedia.editor(draft.preMedia,"pre",12)}</section><section class="panel"><h2>Apresentação no topo do quiz</h2><p class="muted">Material geral disponível durante as perguntas.</p>${CourseMedia.editor(draft.quizMedia,"top",6)}</section><section class="panel"><div class="title-row"><h2>Conteúdo teórico (${draft.theory.length})</h2><button type="button" class="secondary" id="add-theory">+ Adicionar texto</button></div>${draft.theory.map((t,i)=>`<div class="editor-block theory-edit"><label>Título<input name="title" required maxlength="150" value="${esc(t.title)}"></label><label>Texto<textarea name="text" required maxlength="10000" rows="4">${esc(t.text)}</textarea></label><button type="button" class="secondary" data-del-theory="${i}">Remover texto</button></div>`).join('')}</section><section class="panel"><div class="title-row"><h2>Questões (${draft.questions.length})</h2><button type="button" class="secondary" id="add-q">+ Adicionar questão</button></div>${draft.questions.map((q,i)=>`<details class="editor-block question-edit" ${!q.question?'open':''}><summary>Questão ${i+1} · ${esc(q.question.slice(0,90)||'Nova questão')}</summary><label>Tópico<input name="topic" required maxlength="120" value="${esc(q.topic)}"></label><label>Enunciado<textarea name="question" required maxlength="3000" rows="3">${esc(q.question)}</textarea></label>${CourseMedia.editor(q.media,i,3)}${q.options.map((o,j)=>`<label>Alternativa ${letter(j)}<input name="option" required maxlength="1200" value="${esc(o)}"></label>`).join('')}<label>Alternativa correta<select name="correct">${[0,1,2,3].map(j=>`<option value="${j}" ${q.correct===j?'selected':''}>${letter(j)}</option>`).join('')}</select></label><label>Justificativa (opcional)<textarea name="explanation" maxlength="3000" rows="3">${esc(q.explanation)}</textarea></label><button type="button" class="secondary" data-del-q="${i}">Excluir questão</button></details>`).join('')}</section><div class="save-bar"><button type="submit">Salvar matéria e questões</button><span class="muted small">As alterações entram em vigor para novas tentativas.</span></div></form>`);$('#back').onclick=()=>{if(uploading)return toast('Aguarde o envio do arquivo.');if(!dirty||confirm('Sair sem salvar as alterações?'))manage().catch(error);};$('#course-form').oninput=()=>dirty=true;$('#course-form').addEventListener('invalid',e=>{const d=e.target.closest('details');if(d)d.open=true;},true);function mutate(fn,slot){if(uploading)return toast('Aguarde o envio do arquivo.');capture();const y=window.scrollY,opened=[...app.querySelectorAll('.question-edit')].map(x=>x.open);fn();dirty=true;draw();app.querySelectorAll('.question-edit').forEach((el,i)=>{if(opened[i]||String(i)===String(slot))el.open=true;});window.scrollTo(0,y);}$('#add-theory').onclick=()=>{if(draft.theory.length>=50)return toast('Limite de 50 textos.');mutate(()=>draft.theory.push({title:'',text:''}));};$('#add-q').onclick=()=>{if(draft.questions.length>=200)return toast('Limite de 200 questões.');mutate(()=>draft.questions.push({topic:'',question:'',options:['','','',''],correct:0,explanation:'',media:[]}));const list=app.querySelectorAll('.question-edit');list[list.length-1]?.scrollIntoView({block:'center'});};app.querySelectorAll('[data-del-theory]').forEach(b=>b.onclick=()=>{if(confirm('Remover este texto?'))mutate(()=>draft.theory.splice(Number(b.dataset.delTheory),1));});app.querySelectorAll('[data-del-q]').forEach(b=>b.onclick=()=>{if(confirm('Excluir esta questão da próxima versão da matéria?'))mutate(()=>draft.questions.splice(Number(b.dataset.delQ),1));});app.querySelectorAll('[data-media-upload]').forEach(input=>input.onchange=async()=>{const f=input.files?.[0],slot=input.closest('[data-media-slot]').dataset.mediaSlot,max=slot==='pre'?12:slot==='top'?6:3;if(!f||uploading)return;if(mediaList(slot).length>=max){input.value='';return toast('Limite de arquivos atingido.');}uploading=true;input.disabled=true;const submit=$('#course-form [type="submit"]');submit.disabled=true;toast('Enviando arquivo…');try{const item=await CourseMedia.upload(f);if(!input.isConnected)return;uploading=false;mutate(()=>mediaList(slot).push(item),slot);toast('Arquivo enviado. Salve a matéria para publicar.');}catch(e){error(e);}finally{uploading=false;input.disabled=false;input.value='';submit.disabled=false;}});app.querySelectorAll('[data-media-remove]').forEach(b=>b.onclick=()=>{const slot=b.closest('[data-media-slot]').dataset.mediaSlot;mutate(()=>mediaList(slot).splice(Number(b.dataset.mediaRemove),1),slot);});$('#course-form').onsubmit=async e=>{e.preventDefault();if(uploading)return toast('Aguarde o envio do arquivo.');capture();const b=e.currentTarget.querySelector('[type="submit"]');b.disabled=true;try{await api('/api/admin/course',draft);await manage();toast('Matéria salva com sucesso.');}catch(e){error(e);b.disabled=false;}};}draw();}
boot();

async function marketingPreferences(){const data=await api('/api/marketing-preferences');set(`<button class="secondary" id="back">Voltar ao painel</button><section class="panel marketing-panel"><span class="eyebrow">Privacidade e contato</span><h1>Meu WhatsApp</h1><p class="muted">O cadastro é opcional e não altera suas notas nem seu acesso. Você pode retirar a autorização quando desejar.</p><form id="marketing-form"><label for="pref-phone">WhatsApp</label><input type="tel" inputmode="tel" autocomplete="tel" id="pref-phone" maxlength="40" value="${esc(data.contact?.number||'')}"><label class="checkline marketing-consent"><input type="checkbox" id="pref-consent" ${data.contact?'checked':''}><span>${esc(data.consentText)}</span></label><div class="actions"><button type="submit">Salvar preferências</button><button type="button" class="secondary" id="revoke-contact">Cancelar autorização e remover número</button></div></form></section>`);$('#back').onclick=()=> (user.role==='instructor'?instructor():student()).catch(error);$('#marketing-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{await api('/api/marketing-preferences',{whatsapp:$('#pref-phone').value,marketingConsent:$('#pref-consent').checked,revoke:!$('#pref-consent').checked});toast('Preferências atualizadas.');await marketingPreferences();}catch(e){error(e);b.disabled=false;}};$('#revoke-contact').onclick=async()=>{try{await api('/api/marketing-preferences',{revoke:true});await marketingPreferences();toast('Autorização cancelada e número removido.');}catch(e){error(e);}};}
async function marketingContacts(){const rows=await api('/api/admin/marketing-contacts');set(`<div class="title-row"><div><button class="secondary" id="back">Voltar à administração</button><p></p><span class="eyebrow">Relacionamento e divulgação</span><h1>Contatos WhatsApp</h1><p class="muted">Lista de alunos que autorizaram comunicações comerciais. Números autodeclarados, sem verificação de titularidade.</p></div><a class="btn" href="/api/admin/marketing-contacts.csv">Exportar CSV</a></div><div class="metrics">${metric('CONTATOS AUTORIZADOS',rows.length,'Registros ativos')}${metric('NÚMEROS DISTINTOS',new Set(rows.map(r=>r.number)).size,'Antes de qualquer envio, confirme o destinatário')}</div><section class="panel"><h2>Base de contatos</h2><p class="muted small">Use apenas contatos autorizados e confirmados como pertencentes ao destinatário. Respeite pedidos de saída e atualize listas exportadas. Não há disparo automático.</p><label for="contact-search">Buscar contato</label><input id="contact-search" type="search" placeholder="Nome, número, empresa ou turma"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>WhatsApp</th><th>Empresa / turma</th><th>Autorizado em</th><th>Verificação</th><th>Ação</th></tr></thead><tbody id="contact-rows"></tbody></table></div></section>`);$('#back').onclick=()=>admin().catch(error);function fill(){const q=$('#contact-search').value.toLowerCase().trim();const list=rows.filter(r=>[r.name,r.number,r.company,r.login].some(x=>String(x||'').toLowerCase().includes(q)));$('#contact-rows').innerHTML=list.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.number)}</td><td>${esc(r.company||'—')}</td><td>${esc(date(r.authorizedAt))}</td><td><span class="pill pending">Não verificado</span></td><td><button class="secondary" data-remove-contact="${r.uid}">Remover</button></td></tr>`).join('')||'<tr><td colspan="6">Nenhum contato autorizado encontrado.</td></tr>';app.querySelectorAll('[data-remove-contact]').forEach(b=>b.onclick=async()=>{if(!confirm('Remover este contato da base de divulgação?'))return;try{await api('/api/admin/marketing-contacts/remove',{uid:Number(b.dataset.removeContact)});await marketingContacts();toast('Contato removido.');}catch(e){error(e);}});}$('#contact-search').oninput=fill;fill();}

function staffHome(){return user.role==='admin'?admin():instructor();}
async function instructor(){const courses=await api('/api/admin/courses');set(`<div class="title-row"><div><span class="eyebrow"><span class="pill done">Instrutor</span></span><h1>Painel do instrutor</h1><p class="muted">Gerencie os acessos dos alunos, prepare avaliações e conduza competições ao vivo.</p></div><div class="actions"><button id="manage">Matérias e questões</button><a class="btn" href="/corrida">Arena ao vivo</a><button class="secondary" id="own-contact">Meu WhatsApp</button></div></div><section class="arena-banner"><div><span class="eyebrow">CENTRAL DE COMPETIÇÕES</span><h2>Conduza sua turma.</h2><p>Acompanhe acertos, progresso e classificação dos participantes em tempo real.</p><a class="btn arena-cta" href="/corrida">Abrir Arena ao Vivo</a></div>${bannerScene}</section><div class="metrics">${metric('MATÉRIAS',courses.length,'Banco compartilhado')}${metric('QUESTÕES',courses.reduce((n,c)=>n+c.questions.length,0),'Questões cadastradas')}${metric('PUBLICADAS',courses.filter(c=>c.published).length,'Disponíveis aos alunos')}</div><section class="panel"><h2>Cadastrar aluno</h2><p class="muted">Crie um acesso individual. Somente a administração pode atribuir perfis de instrutor.</p><form id="create-student"><div class="form-grid"><div><label>Nome completo<input name="name" required maxlength="120"></label></div><div><label>Empresa / turma<input name="company" maxlength="120"></label></div><div><label>Usuário<input name="login" required minlength="3" maxlength="80" autocomplete="off"></label></div><div><label>Senha inicial<input name="password" type="password" required minlength="8" maxlength="100" autocomplete="new-password"></label></div></div><button class="full">Criar acesso do aluno</button></form></section>`);$('#manage').onclick=()=>manage().catch(error);$('#own-contact').onclick=()=>marketingPreferences().catch(error);$('#create-student').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button');btn.disabled=true;try{await api('/api/students',Object.fromEntries(new FormData(form)));form.reset();toast('Aluno cadastrado com sucesso.');}catch(e){error(e);}finally{btn.disabled=false;}};}
function registrationCompanyLabel(status){return ({company:"Empresa selecionada",none:"Sem vínculo com empresa",unknown:"Não sabe informar"})[status]||"";}
async function usersAdmin(){const users=await api('/api/admin/users');const label=r=>({admin:'Administrador',instructor:'Instrutor',student:'Aluno'}[r]||r);const accessLabel=r=>({active:'Ativo',blocked:'Bloqueado',temporary:'Bloqueado temporariamente',expired:'Acesso vencido',deleted:'Excluído'}[r]||r);const fmtDate=v=>v?new Date(v).toLocaleString('pt-BR'):'Sem prazo';set(`<div class="title-row"><div><button class="secondary" id="back">Voltar à administração</button><p></p><span class="eyebrow">Gestão de acessos</span><h1>Usuários e perfis</h1><p class="muted">Atribua a tag Instrutor a uma conta existente ou crie um novo acesso. Alterar o perfil encerra as sessões da conta.</p></div></div><section class="panel"><h2>Novo usuário</h2><form id="create-user"><div class="form-grid"><div><label>Nome completo<input name="name" required maxlength="120"></label></div><div><label>Empresa / turma<input name="company" maxlength="120"></label></div><div><label>Usuário<input name="login" required minlength="3" maxlength="80" autocomplete="off"></label></div><div><label>Senha inicial<input name="password" type="password" required minlength="8" maxlength="100" autocomplete="new-password"></label></div><div><label>Perfil<select name="role"><option value="student">Aluno</option><option value="instructor">Instrutor</option></select></label></div></div><button class="full">Cadastrar usuário</button></form></section><section class="panel"><div class="title-row"><h2>Usuários cadastrados</h2><a class="btn secondary" href="/api/admin/education.csv" download>Exportar escolaridade e interesses (CSV)</a></div><p class="muted small">O CSV inclui alunos não excluídos, inclusive cadastros anteriores sem escolaridade. O interesse informado não autoriza publicidade.</p><p class="muted small">Bloqueie, defina o prazo de acesso ou exclua contas. A exclusão impede o login e preserva o histórico acadêmico. Datas no horário local deste dispositivo.</p><div id="access-editor" hidden></div><p class="muted small">Instrutores podem cadastrar alunos, criar e editar matérias e conduzir todas as rodadas da arena. Configurações, publicidade, contatos e gestão de perfis são exclusivos do administrador. Os conteúdos e a arena são compartilhados.</p><label>Buscar usuário<input id="user-search" type="search" placeholder="Nome, telefone, empresa, escolaridade ou curso"></label><div class="table-wrap"><table><thead><tr><th>Nome / usuário</th><th>Empresa / turma</th><th>Escolaridade</th><th>Curso técnico de interesse</th><th>Perfil</th><th>Acesso / validade</th><th>Ações</th></tr></thead><tbody id="user-rows"></tbody></table></div></section>`);$('#back').onclick=()=>admin().catch(error);function fill(){const term=$('#user-search').value.trim().toLowerCase();$('#user-rows').innerHTML=users.filter(u=>[u.name,u.login,u.company,registrationCompanyLabel(u.companyStatus),u.phone,u.educationStatus,u.educationGrade,u.technicalInterest,label(u.role),accessLabel(u.accessStatus)].join(' ').toLowerCase().includes(term)).map(u=>`<tr><td><b>${esc(u.name)}</b><br><span class="muted small">${esc(u.login)}</span>${u.phone?`<br><span class="small">${esc(u.phone)} · ${u.phoneVerifiedAt?'Verificado anteriormente por SMS':'Informado, sem verificação'}</span>`:'<br><span class="small muted">Telefone não cadastrado</span>'}</td><td>${esc(u.company||registrationCompanyLabel(u.companyStatus)||'—')}</td><td class="education-cell">${esc(u.educationStatus||'Não informado')}${u.educationGrade?`<br><span class="muted small">${esc(u.educationGrade)}</span>`:''}</td><td class="education-cell">${esc(u.technicalInterest||'Não informado')}</td><td><span class="pill ${u.role==='instructor'?'done':u.role==='admin'?'pending':''}">${esc(label(u.role))}</span></td><td><b>${esc(accessLabel(u.accessStatus))}</b><br><span class="small muted">Validade: ${esc(fmtDate(u.accessUntil))}${u.accessStatus==='temporary'?'<br>Bloqueado até: '+esc(fmtDate(u.blockedUntil)):''}</span></td><td>${u.role==='admin'?'Conta protegida':u.deletedAt?'Histórico preservado':`<div class="actions"><button class="secondary" data-access-id="${u.id}">Gerenciar acesso</button><button class="secondary" data-role-id="${u.id}">${u.role==='student'?'Tornar instrutor':'Tornar aluno'}</button><button class="secondary" data-user-password="${u.id}">Senha</button></div>`}</td></tr>`).join('')||'<tr><td colspan="7">Nenhum usuário encontrado.</td></tr>';app.querySelectorAll('[data-access-id]').forEach(b=>b.onclick=()=>editAccess(users.find(u=>u.id===Number(b.dataset.accessId))));app.querySelectorAll('[data-role-id]').forEach(b=>b.onclick=async()=>{const u=users.find(x=>x.id===Number(b.dataset.roleId)),role=u.role==='student'?'instructor':'student';if(!confirm('Alterar o perfil de '+u.name+' para '+label(role)+'? A conta precisará entrar novamente.'))return;b.disabled=true;try{await api('/api/admin/users/role',{id:u.id,role});await usersAdmin();toast('Perfil atualizado.');}catch(e){error(e);b.disabled=false;}});app.querySelectorAll('[data-user-password]').forEach(b=>b.onclick=async()=>{const password=prompt('Nova senha (8 a 100 caracteres):');if(password===null)return;try{await api('/api/admin/users/password',{id:Number(b.dataset.userPassword),password});toast('Senha atualizada.');}catch(e){error(e);}});}function editAccess(u){const box=$('#access-editor');box.hidden=false;box.innerHTML=`<section class="editor-block"><div class="title-row"><h3>Gerenciar acesso · ${esc(u.name)}</h3><button class="secondary" id="close-access">Fechar</button></div><p class="small">Situação: ${esc(accessLabel(u.accessStatus))} · Validade: ${esc(fmtDate(u.accessUntil))}</p><form id="access-form"><label for="access-action">Ação</label><select id="access-action"><option value="block">Bloquear por tempo indeterminado</option><option value="temporary">Bloquear até uma data e hora</option><option value="unblock">Desbloquear</option><option value="expiry">Definir ou renovar validade do acesso</option><option value="unlimited">Remover prazo de validade</option><option value="delete">Excluir conta (preservar histórico)</option></select><div id="access-date-wrap" hidden><label for="access-date">Data e hora (horário local)</label><input type="datetime-local" id="access-date"></div><p class="small muted" id="access-hint"></p><button type="submit">Aplicar alteração</button></form></section>`;const action=$('#access-action'),date=$('#access-date'),wrap=$('#access-date-wrap'),hint=$('#access-hint');function sync(){const needs=['temporary','expiry'].includes(action.value);wrap.hidden=!needs;date.required=needs;hint.textContent=action.value==='delete'?'Exclusão definitiva do acesso: não será possível recuperar a conta pelo painel. As avaliações e o nome nos relatórios serão mantidos.':action.value==='unblock'?'Remove o bloqueio, mas não renova uma validade vencida.':action.value==='unlimited'?'Remove a validade, mas não cancela um bloqueio.':'A alteração encerra as sessões atuais da conta.';}action.onchange=sync;sync();$('#close-access').onclick=()=>{box.hidden=true;box.replaceChildren();};$('#access-form').onsubmit=async e=>{e.preventDefault();const a=action.value,needs=['temporary','expiry'].includes(a);let until=null;if(needs){const d=new Date(date.value);if(!Number.isFinite(d.getTime())||d.getTime()<=Date.now())return toast('Informe uma data e hora futuras.');until=d.toISOString();}if(a==='delete'&&!confirm('Excluir definitivamente o acesso de '+u.name+'? O histórico acadêmico será preservado.'))return;const btn=e.currentTarget.querySelector('button[type=submit]');btn.disabled=true;try{await api('/api/admin/users/access',{id:u.id,action:a,until});await usersAdmin();toast('Acesso atualizado.');}catch(e){error(e);btn.disabled=false;}};box.scrollIntoView({behavior:'smooth',block:'start'});}$('#user-search').oninput=fill;fill();$('#create-user').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await api('/api/students',Object.fromEntries(new FormData(f)));await usersAdmin();toast('Usuário cadastrado.');}catch(e){error(e);b.disabled=false;}};}

async function backupPage(){
 const campaigns=await api('/api/admin/campaigns');
 set(`<button class="secondary" id="backup-back">← Administração</button><p></p><section class="panel"><span class="eyebrow">Segurança e continuidade</span><h1>Backup dos dados</h1><p>Baixe uma cópia dos registros confirmados da plataforma, sem modificar o banco atual.</p><p>Inclui listas de presença, matérias, questões, alternativas, gabaritos, textos de estudo, contas e perfis, resultados, histórico da Arena, contatos autorizados, logo, carrossel e configurações das campanhas.</p><p class="muted">As senhas são preservadas como hashes, nunca em texto aberto. Sessões de login e convites ativos não são reutilizáveis após uma recuperação. Guarde o arquivo em local protegido: ele contém dados pessoais e gabaritos.</p><a class="btn" href="/api/admin/backup.json" download>Baixar backup dos dados (JSON)</a><p class="muted">Para recuperar em outro ambiente, consulte o README do projeto. Não há restauração automática pelo painel. Faça o backup entre competições.</p></section><section class="panel"><h2>Vídeos enviados</h2><p class="muted">Os vídeos MP4/WebM ficam fora do banco. Baixe a pasta DATA_DIR/campaign-media pelo gerenciador de arquivos da hospedagem para preservar os nomes originais. Links do YouTube e imagens publicitárias já estão no JSON. Para as imagens e vídeos didáticos das matérias, copie também DATA_DIR/course-media. O JSON contém apenas as referências e legendas.</p>${campaigns.some(c=>c.hasVideo)?'<p>Há vídeos enviados cadastrados. Inclua a pasta de mídia no backup.</p>':'<p>Nenhum vídeo local cadastrado no momento.</p>'}</section>`);
 $('#backup-back').onclick=()=>admin().catch(error);
}
